import {strict as assert} from "node:assert";
import {PythonSession} from "/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/index.ts";
const task=JSON.parse(process.argv[2]);
const controller=new AbortController();
let reads=0,writes=0;
const session=new PythonSession({limits:{maxSteps:2000000,maxAllocatedBytes:24000000,maxDepth:100},hashSeed:[1n,2n],signal:controller.signal,
  input:{readLine(){
    reads++;
    const bytes:number[]=[];
    const byte=Buffer.alloc(1);
    while(readSync(0,byte,0,1,null)!==0){bytes.push(byte[0]);if(byte[0]===10)break;}
    if(task.cancel){controller.abort();if(task.cancel==="throw")throw Error("service failure");}
    return bytes.length===0?null:Buffer.from(bytes).toString("utf8");
  }},
  output:{write(text){writes++;writeSync(1,text);},flush(){}}
});
const result=session.exec(task.source);
if(task.cancel){
  const expected={status:"terminated",reason:"cancelled",message:"execution cancelled"};
  assert.deepEqual(result,expected);assert.deepEqual(session.eval("1"),expected);
  assert.equal(reads,1);assert.equal(writes,0);
}else{
  if(result.status==="exception"){
    session.globals.set("failure",result.exception);
    throw Error(JSON.stringify(session.eval("str(failure)")));
  }
  assert.equal(result.status,"ok");assert.equal(reads,task.reads);
}

